using Crownfall.Units; namespace Crownfall.Skills { public static class SkillTargetResolver { public static Unit Resolve(Unit caster,SkillDefinition skill,Crownfall.Battle.BattleController battle){if(skill.targetType==SkillTargetType.Self)return caster;if(skill.targetType==SkillTargetType.CurrentTarget&&caster.CurrentTarget!=null&&!caster.CurrentTarget.IsDead)return caster.CurrentTarget;Unit best=null;float score=float.MaxValue;foreach(var u in battle.Units){if(u==null||u.IsDead)continue;bool ally=u.Team==caster.Team;if(skill.targetType==SkillTargetType.LowestHealthAlly){if(!ally)continue;float x=u.HealthPercent;if(x<score){score=x;best=u;}}else{if(ally)continue;float x=skill.targetType==SkillTargetType.FarthestEnemy?-Crownfall.Battle.Grid.GridMath.Manhattan(caster.CurrentCell.Coordinate,u.CurrentCell.Coordinate):Crownfall.Battle.Grid.GridMath.Manhattan(caster.CurrentCell.Coordinate,u.CurrentCell.Coordinate);if(skill.targetType==SkillTargetType.LowestHealthEnemy)x=u.HealthPercent;if(x<score){score=x;best=u;}}}return best;} } }
